insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Poder Executivo definirá a entidade que centralizará as atividades de implementação, coordenação e controle do Cadastro Nacional, que será o órgão central do Sistema Nacional de Registro de Identificação Civil. A União fica autorizada a firmar convênio com os Estados e o Distrito Federal para a implementação do número único. Os órgãos regionais coordenarão no âmbito de cada Unidade da Federação, repassando aos órgãos locais as instruções do órgão central e reportando a este as informações.', '["Executivo define o órgão central do Sistema.","Convênios da União com Estados e DF.","Órgãos regionais coordenam em cada Unidade da Federação."]'::jsonb, '["ATUALIZAÇÃO: parte do dispositivo foi revogada pela Lei nº 12.058, de 2009."]'::jsonb, 'A União firma convênio com um Estado para implantar o número único.', '["Assertiva que atribui a escolha do órgão central ao Poder Legislativo erra: é do Executivo."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
