insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica estabelecido o número de inscrição no Cadastro de Pessoas Físicas (CPF) como número único e suficiente para identificação do cidadão nos bancos de dados de serviços públicos. O CPF deverá constar dos cadastros e documentos de órgãos públicos, do registro civil de pessoas naturais e dos conselhos profissionais, em especial na certidão de nascimento, casamento e óbito; no Documento Nacional de Identificação; no NIT; no PIS ou Pasep; no Cartão Nacional de Saúde; no título de eleitor; na CTPS; na CNH; no certificado militar; na carteira profissional dos conselhos; e em outros registros de bases públicas. O número de identificação de novos documentos emitidos ou reemitidos por órgãos públicos ou conselhos profissionais será o CPF.', '["CPF como número único e suficiente de identificação nos serviços públicos.","Deve constar de certidões, DNI, NIT, PIS, Pasep, título, CTPS, CNH, certificado militar e carteiras profissionais.","Novos documentos usam o CPF como número de identificação."]'::jsonb, '["ATUALIZAÇÃO: lei recente que unifica a identificação em torno do CPF.","O CPF é ''único e suficiente'': não se exige outro número para identificar o cidadão."]'::jsonb, 'O novo título de eleitor passa a trazer o CPF como número de identificação.', '["Assertiva que exige vários números de identificação para o mesmo cidadão nos serviços públicos erra: o CPF é suficiente."]'::jsonb, '[{"termo":"CPF","significado":"Cadastro de Pessoas Físicas da Receita Federal."}]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cpf' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 3º da Lei da Carteira de Identidade passa a determinar que o órgão emissor use, na emissão de novos documentos, o número do CPF como número de registro geral; que os órgãos emissores pesquisem a base do CPF para verificar a integridade das informações e disponibilizem dados cadastrais e biométricos à Receita Federal; e que, se o requerente não estiver inscrito no CPF, o órgão de identificação fará a inscrição.', '["CPF como número de registro geral na Carteira de Identidade.","Pesquisa na base do CPF e compartilhamento de dados com a Receita.","Inscrição no CPF feita pelo órgão de identificação."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei da Carteira de Identidade."]'::jsonb, 'Ao emitir a identidade, o órgão inscreve no CPF quem ainda não tem o número.', '["Assertiva que mantém um número de RG distinto do CPF nos novos documentos erra."]'::jsonb, '[]'::jsonb, '["Lei da Carteira de Identidade"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cpf' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

