insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Poder Público é autorizado a criar sistema de informações visando à coleta e à gestão de dados que orientem o enfrentamento ao tráfico de pessoas.', '["Autorização para criar sistema de informações.","Coleta e gestão de dados."]'::jsonb, '["Faculdade (''é autorizado'')."]'::jsonb, 'Um sistema nacional reúne dados sobre ocorrências de tráfico de pessoas.', '["Assertiva que torna obrigatória a criação do sistema erra: é autorização."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
