on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo acrescentou ao Código de Processo Penal os arts. 13-A e 13-B. O art. 13-A permite que o membro do Ministério Público ou o delegado requisitem, de órgãos públicos ou empresas privadas, dados e informações cadastrais da vítima ou de suspeitos, nos crimes de sequestro, redução a condição análoga à de escravo, tráfico de pessoas, extorsão qualificada, extorsão mediante sequestro e tráfico de crianças, com atendimento em 24 horas. O art. 13-B permite, mediante autorização judicial, requisitar às empresas de telecomunicações os meios técnicos que localizem a vítima ou suspeitos (sinais), sem acesso ao conteúdo, por até 30 dias, renovável uma vez por igual período; o inquérito deve ser instaurado em 72 horas, e, sem manifestação judicial em 12 horas, a autoridade requisita diretamente, comunicando o juiz.', '["Requisição de dados cadastrais sem ordem judicial (art. 13-A).","Resposta em 24 horas.","Localização por sinais com autorização judicial (art. 13-B).","Sem acesso ao conteúdo das comunicações.","Sinais por até 30 dias, renováveis uma vez.","Inquérito em 72 horas."]'::jsonb, '["Dados CADASTRAIS: sem ordem judicial; SINAIS de localização: com ordem judicial, salvo omissão do juiz em 12 horas.","Conteúdo das comunicações exige autorização judicial própria."]'::jsonb, 'A polícia obtém a localização do celular da vítima sequestrada pela torre de cobertura.', '["Assertiva que permite acessar o conteúdo das mensagens com base no art. 13-B erra: ele é vedado sem autorização judicial específica."]'::jsonb, '[{"termo":"Sinal","significado":"Posicionamento da estação de cobertura, setorização e intensidade de radiofrequência."}]'::jsonb, '["Código de Processo Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O inciso V do art. 83 do Código Penal passa a prever que o livramento condicional exige o cumprimento de mais de dois terços da pena nos casos de condenação por crime hediondo, prática de tortura, tráfico ilícito de entorpecentes, tráfico de pessoas e terrorismo, se o apenado não for reincidente específico em crimes dessa natureza.', '["Livramento condicional após mais de dois terços da pena.","Inclui o tráfico de pessoas.","Vedado ao reincidente específico."]'::jsonb, '["ATUALIZAÇÃO: o regime de livramento condicional foi alterado por leis posteriores (Pacote Anticrime); confira a redação vigente do Código Penal.","Dois terços para hediondos e equiparados."]'::jsonb, 'O condenado por tráfico de pessoas só tem livramento condicional após cumprir mais de dois terços.', '["Assertiva que fixa um terço da pena para o livramento do tráfico de pessoas erra."]'::jsonb, '[]'::jsonb, '["Código Penal, art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código Penal passa a vigorar acrescido do art. 149-A, que cria o crime de tráfico de pessoas e substitui os antigos tipos de tráfico para fins de prostituição.', '["Acrescenta o art. 149-A ao Código Penal.","Cria o tipo penal do tráfico de pessoas."]'::jsonb, '["Os antigos arts. 231 e 231-A foram revogados (art. 16)."]'::jsonb, 'O crime de tráfico de pessoas passa a constar do Código Penal.', '["Assertiva que mantém os antigos arts. 231 e 231-A vigentes erra."]'::jsonb, '[]'::jsonb, '["Art. 149-A"]'::jsonb, 'under_review', 'claude'
