insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Tráfico de pessoas: agenciar, aliciar, recrutar, transportar, transferir, comprar, alojar ou acolher pessoa, mediante grave ameaça, violência, coação, fraude ou abuso, com a finalidade de remover-lhe órgãos, tecidos ou partes do corpo; submetê-la a trabalho em condições análogas à de escravo; submetê-la a qualquer tipo de servidão; adoção ilegal; ou exploração sexual. Pena: reclusão de quatro a oito anos e multa. A pena é aumentada de um terço até a metade se o crime for cometido por funcionário público no exercício das funções, contra criança, adolescente, pessoa idosa ou com deficiência, com prevalência de relações de parentesco, domésticas, de dependência ou autoridade, ou se a vítima for retirada do território nacional. A pena é reduzida de um a dois terços se o agente for primário e não integrar organização criminosa.', '["Condutas: agenciar, aliciar, recrutar, transportar, transferir, comprar, alojar ou acolher.","Meios: grave ameaça, violência, coação, fraude ou abuso.","Fins: remoção de órgãos, trabalho escravo, servidão, adoção ilegal ou exploração sexual.","Reclusão de quatro a oito anos e multa.","Aumento de um terço até a metade.","Redução de um a dois terços para primário que não integre organização criminosa."]'::jsonb, '["Os MEIOS (ameaça, violência, coação, fraude ou abuso) integram o tipo; o consentimento da vítima é irrelevante nos casos de vulneráveis.","Há causa de diminuição (''tráfico privilegiado'' do tráfico de pessoas) para primário que não integre organização criminosa.","Crime de competência federal quando houver transnacionalidade."]'::jsonb, 'Recrutar mulheres com falsa promessa de emprego no exterior para exploração sexual é tráfico de pessoas.', '["Assertiva que dispensa a finalidade de exploração para o crime do art. 149-A erra."]'::jsonb, '[{"termo":"Servidão","significado":"Sujeição da pessoa a dependência que limita sua liberdade."}]'::jsonb, '["Art. 13","Lei de Migração"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'trafico-pessoas' and u.unit_key = 'art-149-a'
