insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A violência doméstica e familiar contra a criança e o adolescente constitui uma das formas de violação dos direitos humanos.', '["Violência doméstica contra criança e adolescente é violação de direitos humanos."]'::jsonb, '["Reafirma a natureza de violação de direitos humanos."]'::jsonb, 'A agressão contra a criança em casa é uma violação de direitos humanos.', '["Assertiva que trata a violência doméstica como assunto exclusivamente privado erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-3'
