insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo altera dispositivos do Estatuto da Criança e do Adolescente (arts. 18-B, 70-A, 70-B, 136, 201 e 226) para, entre outras mudanças, garantir tratamento de saúde especializado à vítima; promover estudos e estatísticas sobre a violência; coibir a violência, o tratamento cruel e as formas violentas de educação; promover campanhas educativas; celebrar convênios para erradicar a violência; capacitar de forma permanente polícias, guardas, bombeiros, escolas e Conselhos Tutelares; promover programas de parentalidade positiva e educação sem castigos físicos; e destacar nos currículos escolares conteúdos sobre prevenção e resposta à violência doméstica.', '["Altera arts. 18-B, 70-A, 70-B, 136, 201 e 226 do ECA.","Tratamento de saúde especializado à vítima.","Capacitação permanente de profissionais.","Educação sem castigos físicos e prevenção nos currículos."]'::jsonb, '["ATUALIZAÇÃO: altera o ECA; confira a redação vigente do Estatuto."]'::jsonb, 'As escolas passam a ensinar conteúdos de prevenção à violência doméstica.', '["Assertiva que mantém o ECA inalterado por esta Lei erra: ela altera seis dispositivos."]'::jsonb, '[]'::jsonb, '["Estatuto da Criança e do Adolescente"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'henry-borel' and u.unit_key = 'art-29'
