insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos procedimentos regulados nesta Lei aplicam-se subsidiariamente, no que couber, as disposições do Estatuto da Criança e do Adolescente, da Lei Maria da Penha e da Lei nº 13.431, de 4 de abril de 2017.', '["Aplicação subsidiária do ECA.","Aplicação subsidiária da Lei Maria da Penha.","Aplicação subsidiária da Lei nº 13.431."]'::jsonb, '["Três leis subsidiárias."]'::jsonb, 'Na falta de regra na Lei Henry Borel, aplica-se a Lei Maria da Penha, no que couber.', '["Assertiva que exclui a Lei Maria da Penha das fontes subsidiárias erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
